        { you: { cue: 'Say once — it was so spicy your eyes watered.', t: '吃过一次，辣得我眼泪都出来了。', r: 'Chī guo yí cì, là de wǒ yǎnlèi dōu chūlai le.', en: 'Once. It was so spicy my eyes were streaming.',
          alt: ['吃过一次', '吃过，太辣了', '吃过一次，特别辣'],
          gloss: '吃过 chī guo = have eaten · 一次 yí cì = once · 辣得 là de = so spicy that… (adjective + 得 + result) · 我 wǒ = my · 眼泪 yǎnlèi = tears · 都 dōu = even · 出来了 chūlai le = came out' } },
        { them: { t: '哈哈！那你还想再吃吗？', r: 'Hāhā! Nà nǐ hái xiǎng zài chī ma?', en: 'Ha ha! So would you have it again?' } },
        { you: { cue: 'Say of course — next time you’ll order a broth that isn’t spicy.', t: '当然想！下次我就点一个不辣的锅底。', r: 'Dāngrán xiǎng! Xià cì wǒ jiù diǎn yí gè bú là de guōdǐ.', en: 'Of course! Next time I’ll just order a broth that isn’t spicy.',
          alt: ['想，下次点不辣的', '当然想', '下次我点不辣的'],
          gloss: '当然 dāngrán = of course · 想 xiǎng = want to · 下次 xià cì = next time · 我 wǒ = I · 就 jiù = just · 点 diǎn = order (food) · 一个 yí gè = a · 不辣的 bú là de = non-spicy · 锅底 guōdǐ = hotpot broth' } },
        { them: { t: '下个月我们一起去成都吧？', r: 'Xià gè yuè wǒmen yìqǐ qù Chéngdū ba?', en: 'How about we go to Chengdu together next month?' } },
        { you: { cue: 'Say great idea — you’ve always wanted to see Chengdu.', t: '好主意！我一直都想去成都看看。', r: 'Hǎo zhǔyi! Wǒ yìzhí dōu xiǎng qù Chéngdū kànkan.', en: 'Great idea! I’ve always wanted to go and see Chengdu.',
          alt: ['好主意', '我一直想去成都', '好啊，我一直想去'],
          gloss: '好主意 hǎo zhǔyi = good idea · 我 wǒ = I · 一直 yìzhí = all along · 都 dōu = (emphasis) · 想 xiǎng = want to · 去 qù = go · 成都 Chéngdū · 看看 kànkan = have a look' } }
